import java.util.Scanner;

public class Main {
    static final long mod = 1000000009;
    static final int MAXN = 262144;
    static ModInt[] fact = new ModInt[MAXN];
    static ModInt[] invFact = new ModInt[MAXN];
    static Pair[] dp = new Pair[501];
    static Pair[][] dp2 = new Pair[502][501];

    static class ModInt {
        long value;

        ModInt() {
            this.value = 0;
        }

        ModInt(long v) {
            this.value = v % mod;
            if (this.value < 0) this.value += mod;
        }

        ModInt add(ModInt other) {
            long res = this.value + other.value;
            if (res >= mod) res -= mod;
            return new ModInt(res);
        }

        ModInt subtract(ModInt other) {
            long res = this.value - other.value;
            if (res < 0) res += mod;
            return new ModInt(res);
        }

        ModInt multiply(ModInt other) {
            return new ModInt((this.value * other.value) % mod);
        }

        ModInt pow(long n) {
            ModInt res = new ModInt(1);
            ModInt base = this;
            while (n > 0) {
                if ((n & 1) == 1) res = res.multiply(base);
                base = base.multiply(base);
                n >>= 1;
            }
            return res;
        }

        static ModInt one() {
            return new ModInt(1);
        }

        static ModInt zero() {
            return new ModInt(0);
        }
    }

    static class Pair {
        ModInt first;
        ModInt second;

        Pair(ModInt first, ModInt second) {
            this.first = first;
            this.second = second;
        }
    }

    static ModInt modPow(long base, long exp, long m) {
        ModInt result = new ModInt(1);
        ModInt b = new ModInt(base);
        long e = exp;
        while (e > 0) {
            if ((e & 1) == 1) result = result.multiply(b);
            b = b.multiply(b);
            e >>= 1;
        }
        return result;
    }

    static long inv(long a, long p) {
        if (a == 1) return 1;
        return (1 - p * inv(p % a, a)) / a + p;
    }

    static void initFactorials() {
        fact[0] = new ModInt(1);
        for (int i = 1; i < MAXN; i++) {
            fact[i] = fact[i - 1].multiply(new ModInt(i));
        }
        invFact[MAXN - 1] = new ModInt(1).multiply(fact[MAXN - 1].pow(mod - 2));
        for (int i = MAXN - 2; i >= 0; i--) {
            invFact[i] = invFact[i + 1].multiply(new ModInt(i + 1));
        }
    }

    static ModInt comb(int a, int b) {
        if (a < 0 || b < 0 || a < b) return new ModInt(0);
        return fact[a].multiply(invFact[b]).multiply(invFact[a - b]);
    }

    static Pair multiplyPairs(Pair a, Pair b) {
        return new Pair(a.first.multiply(b.first), a.second.multiply(b.first).add(a.first.multiply(b.second)));
    }

    static Pair addPairs(Pair a, Pair b) {
        return new Pair(a.first.add(b.first), a.second.add(b.second));
    }

    static void initialize() {
        initFactorials();
        dp[0] = new Pair(new ModInt(1), new ModInt(0));
        dp[1] = new Pair(new ModInt(2), new ModInt(0));
        for (int n = 2; n <= 500; n++) {
            Pair sumPair = new Pair(new ModInt(0), new ModInt(0));
            for (int j = 0; j < n; j++) {
                ModInt count = new ModInt(n + 1);
                ModInt sum = new ModInt(0);
                for (int k = 0; k < n; k++) {
                    sum = sum.add(new ModInt(Math.abs(j - k)));
                }
                Pair left = dp[j];
                Pair right = dp[n - 1 - j];
                Pair x = multiplyPairs(left, right);
                x.first = x.first.multiply(comb(n - 1, j));
                x.second = x.second.multiply(comb(n - 1, j));
                x.first = x.first.multiply(count);
                x.second = x.second.multiply(count).add(sum.multiply(count));
                sumPair = addPairs(sumPair, x);
            }
            dp[n] = sumPair;
        }
    }

    static void solve(Scanner sc) {
        int n = sc.nextInt();
        int m = sc.nextInt();
        initialize();
        for (int i = 0; i <= n; i++) {
            for (int k = 0; k <= m; k++) {
                dp2[i][k] = new Pair(ModInt.zero(), ModInt.zero());
            }
        }
        dp2[0][0] = new Pair(new ModInt(1), new ModInt(0));
        for (int i = 0; i < n; i++) {
            for (int k = 0; k <= m; k++) {
                if (dp2[i][k].first.value == 0 && dp2[i][k].second.value == 0) continue;
                for (int j = i; j < n; j++) {
                    int ni = j + 2;
                    if (ni > n) ni = n;
                    int nk = k + j - i + 1;
                    if (nk <= m) {
                        Pair x = multiplyPairs(dp2[i][k], dp[j - i + 1]);
                        x.first = x.first.multiply(comb(nk, k));
                        x.second = x.second.multiply(comb(nk, k));
                        dp2[ni][nk] = addPairs(dp2[ni][nk], x);
                    }
                }
                if (i + 1 <= n && k <= m) {
                    dp2[i + 1][k] = addPairs(dp2[i + 1][k], dp2[i][k]);
                }
            }
        }
        System.out.println(dp2[n][m].second.value);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        solve(sc);
        sc.close();
    }
}
